sp_ListarPagamentosPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarPagamentosPedido`(IN p_idPedido INT)\nBEGIN\n\n    SELECT\n\n        pp.idPagamento,\n\n        pp.idPedido,\n\n        pp.formaPagamento_id,\n\n        pp.valor,\n\n        pp.dthPagamento\n\n    FROM PedidoPagamento pp\n\n    WHERE pp.idPedido = p_idPedido\n\n    ORDER BY pp.dthPagamento ASC;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
